const input = $json;
let context = input.context || {};
if (typeof context === 'string') {
  try { context = JSON.parse(context); } catch (e) { context = {}; }
}
const text = (input.message || '').trim();
const state = input.current_state || 'NEW';

let next_state = state;
let reply = '';
let action = 'NONE';

if (state === 'AWAITING_NEW_DATE') {
  const parsed = new Date(text);
  if (isNaN(parsed.getTime())) {
    next_state = 'AWAITING_NEW_DATE';
    reply = "I couldn't understand that date. Please use a format like 2026-10-15.";
  } else {
    context.requested_date = parsed.toISOString().slice(0, 10);
    action = 'UPDATE_DATE';
  }
} else {
  const match = text.toUpperCase().match(/SD-\d{4,}/);
  if (match) {
    context.tracking_number = match[0];
    action = 'LOOKUP';
  } else {
    next_state = 'AWAITING_TRACKING_NUMBER';
    reply = 'Sure! Which delivery would you like to reschedule? Please share the tracking number (e.g. SD-1042).';
  }
}

return [{
  json: {
    customer_id: input.customer_id,
    phone: input.phone,
    conversation_id: input.conversation_id || null,
    next_state,
    context,
    reply,
    action
  }
}];

const base = $('Process Reschedule State').item.json;
const row = $json;
const ELIGIBLE = ['PENDING', 'CONFIRMED', 'OUT_FOR_DELIVERY'];
let reply, next_state, action = 'NONE';
if (!row.status) {
  reply = `I couldn't find a delivery with tracking number ${base.context.tracking_number}. Please double-check and try again.`;
  next_state = 'AWAITING_TRACKING_NUMBER';
} else if (!ELIGIBLE.includes(row.status)) {
  reply = `That delivery is already ${row.status.replace(/_/g, ' ').toLowerCase()}, so it can't be rescheduled automatically. I've sent this to our operations team to help.`;
  next_state = 'HUMAN_ESCALATION';
  action = 'ESCALATE_INELIGIBLE';
} else {
  reply = 'What date would you like to reschedule to? (e.g. 2026-10-15)';
  next_state = 'AWAITING_NEW_DATE';
}
return [{ json: { ...base, reply, next_state, action } }];

const f = $('Finalize Payload').item.json;
return [{
  json: {
    reply: f.reply,
    next_state: f.next_state,
    customer_id: f.customer_id,
    conversation_id: f.conversation_id
  }
}];
